import unittest
from candidate import how_many_times


class TestHowManyTimes(unittest.TestCase):
    def test_empty_string_returns_zero(self):
        self.assertEqual(how_many_times('', 'a'), 0)

    def test_single_char_in_single_char(self):
        self.assertEqual(how_many_times('a', 'a'), 1)

    def test_single_char_not_in_string(self):
        self.assertEqual(how_many_times('b', 'a'), 0)

    def test_substring_longer_than_string(self):
        self.assertEqual(how_many_times('ab', 'abc'), 0)

    def test_substring_longer_than_string_by_one(self):
        self.assertEqual(how_many_times('abc', 'abcd'), 0)

    def test_overlapping_single_char(self):
        self.assertEqual(how_many_times('aaa', 'a'), 3)

    def test_overlapping_two_char(self):
        self.assertEqual(how_many_times('aaaa', 'aa'), 3)

    def test_overlapping_three_char(self):
        self.assertEqual(how_many_times('aaaaa', 'aaa'), 3)

    def test_non_overlapping_substring(self):
        self.assertEqual(how_many_times('ababab', 'ab'), 3)

    def test_overlapping_aba(self):
        self.assertEqual(how_many_times('abab', 'aba'), 2)

    def test_substring_at_start(self):
        self.assertEqual(how_many_times('hello', 'he'), 1)

    def test_substring_at_end(self):
        self.assertEqual(how_many_times('hello', 'lo'), 1)

    def test_substring_in_middle(self):
        self.assertEqual(how_many_times('hello', 'ell'), 1)

    def test_no_match_returns_zero(self):
        self.assertEqual(how_many_times('abc', 'xyz'), 0)

    def test_substring_appears_multiple_times(self):
        self.assertEqual(how_many_times('abcabcabc', 'abc'), 3)

    def test_all_same_chars_substring_two(self):
        self.assertEqual(how_many_times('aaaa', 'aa'), 3)

    def test_all_same_chars_substring_three(self):
        self.assertEqual(how_many_times('aaaa', 'aaa'), 2)

    def test_all_same_chars_substring_four(self):
        self.assertEqual(how_many_times('aaaa', 'aaaa'), 1)

    def test_empty_substring_in_nonempty_string(self):
        self.assertEqual(how_many_times('abc', ''), 4)

    def test_empty_string_and_empty_substring(self):
        self.assertEqual(how_many_times('', ''), 1)

    def test_none_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            how_many_times(None, 'a')

    def test_none_substring_raises_type_error(self):
        with self.assertRaises(TypeError):
            how_many_times('abc', None)

    def test_both_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            how_many_times(None, None)

    def test_integer_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            how_many_times(123, 'a')

    def test_integer_substring_raises_type_error(self):
        with self.assertRaises(TypeError):
            how_many_times('abc', 123)

    def test_mixed_case_sensitivity(self):
        self.assertEqual(how_many_times('AbAbAb', 'a'), 0)

    def test_mixed_case_substring_not_found(self):
        self.assertEqual(how_many_times('hello', 'Hello'), 0)

    def test_substring_equal_to_string(self):
        self.assertEqual(how_many_times('hello', 'hello'), 1)

    def test_substring_one_char_in_long_string(self):
        self.assertEqual(how_many_times('a' * 10, 'a'), 10)

    def test_substring_of_two_in_tens(self):
        self.assertEqual(how_many_times('a' * 10, 'aa'), 9)

    def test_whitespace_substring(self):
        self.assertEqual(how_many_times('a b c', ' '), 2)

    def test_whitespace_in_string(self):
        self.assertEqual(how_many_times('  hello  ', '  '), 1)

    def test_special_characters(self):
        self.assertEqual(how_many_times('!@!@!', '!@'), 2)

    def test_unicode_characters(self):
        self.assertEqual(how_many_times('héllo', 'é'), 1)

    def test_very_long_string_single_char(self):
        self.assertEqual(how_many_times('x' * 1000, 'x'), 1000)

    def test_substring_of_length_one_in_two_char_string(self):
        self.assertEqual(how_many_times('aa', 'a'), 2)

    def test_substring_of_length_two_in_three_char_string(self):
        self.assertEqual(how_many_times('aba', 'ba'), 1)

    def test_substring_of_length_three_in_three_char_string(self):
        self.assertEqual(how_many_times('aba', 'aba'), 1)

    def test_return_type_is_int(self):
        self.assertIsInstance(how_many_times('abc', 'b'), int)


if __name__ == '__main__':
    unittest.main()
